pub async fn process_rpc_custody_columns(
    self: Arc<NetworkBeaconProcessor<T>>,
    block_root: Hash256,
    custody_columns: DataColumnSidecarList<T::EthSpec>,
    seen_timestamp: Duration,
    process_type: BlockProcessType,
) {
    // custody_columns must always have at least one element
    let Some(slot) = custody_columns.first().map(|d| d.slot()) else {
        return;
    };

    if let Ok(current_slot) = self.chain.slot()
        && current_slot == slot
    {
        let delay = get_slot_delay_ms(seen_timestamp, slot, &self.chain.slot_clock);
        metrics::observe_duration(&metrics::BEACON_BLOB_RPC_SLOT_START_DELAY_TIME, delay);
    }

    let mut indices = custody_columns.iter().map(|d| d.index).collect::<Vec<_>>();
    indices.sort_unstable();
    debug!(
        ?indices,
        %block_root,
        %slot,
        "RPC custody data columns received"
    );

    let mut result = self
        .chain
        .process_rpc_custody_columns(custody_columns)
        .await;
    register_process_result_metrics(&result, metrics::BlockSource::Rpc, "custody_columns");

    match &result {
        Ok(availability) => match availability {
            AvailabilityProcessingStatus::Imported(hash) => {
                debug!(
                    result = "imported block and custody columns",
                    block_hash = %hash,
                    "Block components retrieved"
                );
                self.chain.recompute_head_at_current_slot().await;
            }
            AvailabilityProcessingStatus::MissingComponents(_, _) => {
                debug!(
                    block_hash = %block_root,
                    "Missing components over rpc"
                );
                // Attempt reconstruction here before notifying sync, to avoid sending out more requests
                // that we may no longer need.
                // We don't publish columns reconstructed from rpc columns to the gossip network,
                // as these are likely historic columns.
                let publish_columns = false;
                if let Some(availability) = self
                    .attempt_data_column_reconstruction(block_root, publish_columns)
                    .await
                {
                    result = Ok(availability)
                }
            }
        },
        Err(BlockError::DuplicateFullyImported(_)) => {
            debug!(
                block_hash = %block_root,
                "Custody columns have already been imported"
            );
        }
        Err(e) => {
            warn!(
                error = ?e,
                block_hash = %block_root,
                "Error when importing rpc custody columns"
            );
        }
    }

/// imported or errors.
pub async fn process_rpc_custody_columns(
    self: &Arc<Self>,
    custody_columns: DataColumnSidecarList<T::EthSpec>,
) -> Result<AvailabilityProcessingStatus, BlockError> {
    let Ok((slot, block_root)) = custody_columns
        .iter()
        .map(|c| (c.slot(), c.block_root()))
        .unique()
        .exactly_one()
    else {
        return Err(BlockError::InternalError(
            "Columns should be from the same block".to_string(),
        ));
    };

    // If this block has already been imported to forkchoice it must have been available, so
    // we don't need to process its columns again.
    if self
        .canonical_head
        .fork_choice_read_lock()
        .contains_block(&block_root)
    {
        return Err(BlockError::DuplicateFullyImported(block_root));
    }

    // Reject RPC columns referencing unknown parents. Otherwise we allow potentially invalid data
    // into the da_checker, where invalid = descendant of invalid blocks.
    // Note: custody_columns should have at least one item and all items have the same parent root.
    if let Some(parent_root) = custody_columns.iter().map(|c| c.block_parent_root()).next()
        && !self
            .canonical_head
            .fork_choice_read_lock()
            .contains_block(&parent_root)
    {
        return Err(BlockError::ParentUnknown { parent_root });
    }

    self.emit_sse_data_column_sidecar_events(
        &block_root,
        custody_columns.iter().map(|column| column.as_ref()),
    );

    let r = self
        .check_rpc_custody_columns_availability_and_import(slot, block_root, custody_columns)
        .await;
    self.remove_notified(&block_root, r)
}

pub async fn reconstruct_data_columns(
    self: &Arc<Self>,
    block_root: Hash256,
) -> Result<
    Option<(
        AvailabilityProcessingStatus,
        DataColumnSidecarList<T::EthSpec>,
    )>,
    BlockError,
> {
    // As of now we only reconstruct data columns on supernodes, so if the block is already
    // available on a supernode, there's no need to reconstruct as the node must already have
    // all columns.
    if self
        .canonical_head
        .fork_choice_read_lock()
        .contains_block(&block_root)
    {
        return Ok(None);
    }

    let data_availability_checker = self.data_availability_checker.clone();

    let result = self
        .task_executor
        .spawn_blocking_handle(
            move || data_availability_checker.reconstruct_data_columns(&block_root),
            "reconstruct_data_columns",
        )
        .ok_or(BeaconChainError::RuntimeShutdown)?
        .await

